keys=[];sols=[];evidence=[]
for qid in dict.fromkeys(r['question']for r in M if r['field'][':db/id']not in duplicates):
 q=Q[qid];sid=q[':question/math-academy-id'];aids,solution=SOL[sid];targets=[r for r in M if r['question']==qid and r['field'][':db/id']not in duplicates];assert len(targets)==len(aids),(sid,len(targets),aids)
 # ID membership maps multipart answers to their actual field, never Pull order.
 for aid in aids:
  match=[r for r in targets if any(a[':db/id']==aid for a in r['field'][':answer-field/choices'])];assert len(match)==1,(sid,aid);r=match[0];kp=next(k for t,k,qq in D['links']if qq==qid);canonical=K[kp][':knowledge-point/canonical-example'][':db/id'];keys.append({'question':qid,'field':r['field'][':db/id'],'before':None,'answer':aid,'source_identity':sid,'reason':'Independently derived completion using an existing answer owned by this field.','evidence':{'canonical_example':canonical,'classification':'authored completion, not an observed source answer','solution_entity':qid},'confidence':'high'})
 solution=solution.replace(r'\ne','NE_OPERATOR_TOKEN').replace(r'\n','\n').replace('NE_OPERATOR_TOKEN',r'\ne');validate_math_structure(solution)
 if ':question/worked-solution'not in q:sols.append({'entity':qid,'attribute':'question/worked-solution','before':None,'after':solution,'reason':'Supply the independently verified worked solution accompanying missing-key completion.','evidence':{'source_identity':sid,'classification':'authored completion'},'confidence':'high'})
 evidence.append({'question':qid,'source_identity':sid,'existing_solution_preserved':q.get(':question/worked-solution'),'independent_derivation':solution,'selected_answers':[a for f in q[':question/answer-fields']for a in f[':answer-field/choices']if a[':db/id']in aids]})
(H/'missing-key-completions.json').write_text(json.dumps(keys,indent=2));(H/'completion-solutions.json').write_text(json.dumps(sols,indent=2));(H/'completion-evidence.json').write_text(json.dumps(evidence,indent=2));print('keys',len(keys),'questions',len(evidence),'new solutions',len(sols),'legacy duplicate targets excluded',len(duplicates))
